def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in into s_out."""
    # Simple approach: find first differing position and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # Strings are identical up to min length
        if len(s_in) == len(s_out):
            return "", "", -1  # No change needed
        elif len(s_in) < len(s_out):
            # Insertion at end
            return "", s_out[len(s_in):], len(s_in)
        else:
            # Deletion at end  
            return s_in[len(s_out):], "", len(s_out)

    # Find what needs to be replaced
    old_sub = ""
    new_sub = ""

    # Look for substring matches
    for i in range(pos, len(s_in)):
        for j in range(pos, len(s_out) + 1):
            if s_in[pos:i+1] == s_out[pos:j]:
                old_sub = s_in[pos:i+1]
                new_sub = s_out[pos:j]
                break
        if old_sub:
            break

    if not old_sub:
        # If no substring match found, check if we're replacing single char
        old_sub = s_in[pos] if pos < len(s_in) else ""
        new_sub = s_out[pos] if pos < len(s_out) else ""

    return old_sub, new_sub, pos

# Analyze the changed pairs
changed = [(3, 'agxd', 'afkbuaj'), (4, 'kvdebu', 'kvjebu')]

for idx, s_in, s_out in changed:
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
    print(f"Pair {idx}: '{s_in}' -> '{s_out}'")
    print(f"  Old sub: '{old_sub}', New sub: '{new_sub}', Position: {pos}")

